using Npgsql; using System; await using var conn = new NpgsqlConnection("Host=localhost;Port=5433;Database=enjoyeveryday;Username=postgres;Password=postgres"); await conn.OpenAsync(); await using var cmd = new NpgsqlCommand("SELECT scheduled_date, classroom_id, status FROM experience_schedules;", conn); await using var reader = await cmd.ExecuteReaderAsync(); while(await reader.ReadAsync()) Console.WriteLine($"Date: {reader.GetDateTime(0).ToString("yyyy-MM-dd")}, ClassroomID: {reader.GetGuid(1)}, Status: {reader.GetString(2)}");
